#pragma warning disable CA1725
using ClosedXML.Excel;
using WhatsBiz.Application.Common.Interfaces;
using WhatsBiz.Domain.Customers;
namespace WhatsBiz.Infrastructure.Customers;
public sealed class CustomerSpreadsheetService : ICustomerSpreadsheetService { private static readonly string[] H = ["Customer Code", "Customer Name", "Customer Type", "GSTIN", "PAN", "Email", "Mobile", "Currency", "Credit Limit", "Active"]; public byte[] Export(IReadOnlyCollection<Customer> cs) { using var w = new XLWorkbook(); var s = w.AddWorksheet("Customers"); Head(s); var r = 2; foreach (var c in cs) { s.Cell(r, 1).Value = c.CustomerCode; s.Cell(r, 2).Value = c.CustomerName; s.Cell(r, 3).Value = c.CustomerType; s.Cell(r, 4).Value = c.GSTIN; s.Cell(r, 5).Value = c.PAN; s.Cell(r, 6).Value = c.Email; s.Cell(r, 7).Value = c.Mobile; s.Cell(r, 8).Value = c.Currency; s.Cell(r, 9).Value = c.CreditLimit; s.Cell(r, 10).Value = c.IsActive; r++; } return Save(w); } public byte[] Template() { using var w = new XLWorkbook(); var s = w.AddWorksheet("Customers"); Head(s); s.Cell(2, 1).Value = "CUS-001"; s.Cell(2, 2).Value = "Sample Customer"; s.Cell(2, 3).Value = "Retail"; s.Cell(2, 8).Value = "INR"; s.Cell(2, 10).Value = true; return Save(w); } public IReadOnlyCollection<CustomerImportRow> Read(byte[] d) { using var m = new MemoryStream(d); using var w = new XLWorkbook(m); return w.Worksheet(1).RowsUsed().Skip(1).Where(r => !r.Cell(1).IsEmpty()).Select(r => new CustomerImportRow(r.RowNumber(), r.Cell(1).GetString(), r.Cell(2).GetString(), r.Cell(3).GetString(), N(r.Cell(4).GetString()), N(r.Cell(5).GetString()), N(r.Cell(6).GetString()), N(r.Cell(7).GetString()), r.Cell(8).GetString(), r.Cell(9).TryGetValue<decimal>(out var v) ? v : 0, !r.Cell(10).IsEmpty() && r.Cell(10).GetBoolean())).ToArray(); } private static void Head(IXLWorksheet s) { for (var i = 0; i < H.Length; i++) { s.Cell(1, i + 1).Value = H[i]; s.Cell(1, i + 1).Style.Font.Bold = true; } } private static byte[] Save(XLWorkbook w) { using var m = new MemoryStream(); w.SaveAs(m); return m.ToArray(); } private static string? N(string x) => string.IsNullOrWhiteSpace(x) ? null : x.Trim(); }
